/**
 * What an initiative's last two stages act on, resolved from the initiative itself — never an id
 * the caller has to carry across a conversation. `release_prepare` and `proposal_prepare`
 * (`release.ts`) take only the initiative: IMPROVE and PROMOTE/VERIFY may each open in a fresh
 * conversation, and the ids they would otherwise need were only ever in an earlier one's tool
 * responses.
 *
 * The link is the one the platform already writes: `<initiative>/findings.md` carries
 * `eval_run_id` in its envelope (`findings-doc.ts`, regenerated by every `finding_record` naming
 * the initiative), `improvement_start` refuses a finding from any other eval_run, and every
 * `zz.improvement_run` names its eval_run. No new id is persisted anywhere.
 *
 * The document is a ROW — `doc` plus `doc_revision`, the store this used to be a file in is
 * retired (`versions.ts`) — so `evalRunOf` reads it back through `loadDocument`, the same
 * composed text `document_read` answers with: the revision's `fields` payload carries the
 * envelope's open keys, `eval_run_id` among them, and `documentText` renders them back.
 */
import { parseCaller, parseEnvelope } from "@zz/contracts";
import { requestHeaders } from "@zz/mcp-http";
import type pg from "pg";

import { safeName } from "../paths.js";
import { teamFor } from "../platform-db.js";
import { loadDocument } from "../versions.js";

/** The eval_run a findings.md's text records (null: no such document), or the refusal naming
 *  what is missing. Pure, so a check drives it without the store. */
export function evalRunIn(findingsMd: string | null, initiative: string): string | { error: string } {
  const evalRunId = findingsMd === null ? undefined : parseEnvelope(findingsMd).eval_run_id;
  if (!evalRunId) {
    return {
      error: `ERROR: no_eval_run — ${initiative}/findings.md does not exist or records no eval_run_id; ` +
        "EXPLAIN writes it (finding_record with this initiative) before IMPROVE opens an improvement run",
    };
  }
  return evalRunId;
}

/** The eval_run the initiative's own findings.md records, or the refusal `evalRunIn` names.
 *
 * A document is filed under a TEAM, so the team is resolved first and off the caller — the same
 * resolution `findings-doc.ts` and `improvement-doc.ts` file the document with — because a
 * team-blind read of a path answers with whatever team happens to hold that name, and an
 * initiative's slug is unique only within one team.
 *
 * DELIBERATE: a caller this deployment cannot place is refused by name rather than answered with
 * `evalRunIn(null, …)`'s "does not exist", which would send a reader looking for a document that
 * is not the thing missing. */
async function evalRunOf(initiative: string): Promise<string | { error: string }> {
  const bad = safeName(initiative, "initiative");
  if (bad) return { error: bad };
  const team = await teamFor(parseCaller(requestHeaders()).email);
  if (!team) {
    return { error:
      "ERROR: this caller resolves to no team, so no document of theirs can be read — " +
      `\`${initiative}/findings.md\` is filed under a team, and there is nothing to file it on` };
  }
  const loaded = await loadDocument(team, `${initiative}/findings.md`);
  // Every way the row can fail to answer — no such document, no current revision, a revision
  // that retained no bytes — is the same fact to a caller asking for an eval_run_id, and
  // `evalRunIn` states it: a findings.md with no eval_run_id refuses BY NAME.
  return evalRunIn(loaded.ok ? loaded.text : null, initiative);
}

/** The candidate this initiative releases: a `valid` one (built and gated) of its improvement
 *  runs. With `candidateId`, that one, refused by name unless it is `valid` and on this eval_run;
 *  without, the only one, refused by name when there is none or when there are several (listing
 *  them — pass `candidate_id` to choose). */
export async function releasableCandidateOf(
  p: pg.Pool, initiative: string, candidateId?: string,
): Promise<string | { error: string }> {
  const evalRunId = await evalRunOf(initiative);
  return typeof evalRunId === "string" ? releasableCandidateOn(p, initiative, evalRunId, candidateId) : evalRunId;
}

/** `releasableCandidateOf` once the eval_run is known — exported for its check. */
export async function releasableCandidateOn(
  p: pg.Pool, initiative: string, evalRunId: string, candidateId?: string,
): Promise<string | { error: string }> {
  const ids = (await p.query<{ id: string }>(`
    select c.id::text as id
      from zz.candidate c join zz.improvement_run ir on ir.id = c.improvement_run_id
     where ir.eval_run_id = $1::uuid and c.status = 'valid'
     order by c.created_at`, [evalRunId])).rows.map((r) => r.id);
  if (candidateId) {
    if (ids.includes(candidateId)) return candidateId;
    return {
      error: `ERROR: not_eligible — candidate ${candidateId} is not a valid (built and gated) candidate of ` +
        `${initiative}'s improvement runs (eval_run ${evalRunId}); candidate_validate decides that in IMPROVE`,
    };
  }
  if (ids.length === 1) return ids[0];
  return {
    error: ids.length === 0
      ? `ERROR: not_eligible — no candidate of ${initiative}'s improvement runs (eval_run ${evalRunId}) ` +
        "is valid; candidate_validate makes one valid once its build and gate pass in IMPROVE"
      : `ERROR: ambiguous_candidate — ${ids.length} candidates of ${initiative}'s improvement runs ` +
        `are valid (${ids.join(", ")}); pass candidate_id naming the one to release`,
  };
}

/** The initiative's improvement run. DELIBERATE: the newest one, not a refusal when there are
 *  several — IMPROVE may open a fresh `improvement_start` on the same eval_run, and refusing
 *  that would leave a non-owned subject no way to its proposal. Refused by name when there is
 *  none. */
export async function improvementRunOf(p: pg.Pool, initiative: string): Promise<string | { error: string }> {
  const evalRunId = await evalRunOf(initiative);
  return typeof evalRunId === "string" ? improvementRunOn(p, initiative, evalRunId) : evalRunId;
}

/** `improvementRunOf` once the eval_run is known — exported for its check. */
export async function improvementRunOn(
  p: pg.Pool, initiative: string, evalRunId: string,
): Promise<string | { error: string }> {
  const row = (await p.query<{ id: string }>(`
    select id::text as id from zz.improvement_run
     where eval_run_id = $1::uuid order by created_at desc limit 1`, [evalRunId])).rows[0];
  return row?.id ?? {
    error: `ERROR: no_improvement_run — ${initiative}'s eval_run ${evalRunId} has no improvement run; ` +
      "improvement_start opens one (or, with nothing plugin-owned to improve, skip: true closes without a proposal)",
  };
}
